import React from "react";
import type { Meta, StoryObj } from "@storybook/react";
import { airbus as tokens } from "@airbus/design-tokens";
import Launch from "@material-design-icons/svg/filled/launch.svg?react";
import Button from "../Button";
import Chip from "../Chip";
import Inline from "../Inline";
import Stack from "../Stack";
import Hidden from "./Hidden";

const Breakpoints = ["xxs", "xs", "sm", "md", "lg", "xl", "xxl"];

const meta: Meta<typeof Hidden> = {
  id: "Components/Hidden",
  title: "General/Layout/Utilities/Hidden",
  component: Hidden,
  argTypes: {
    on: { options: Breakpoints },
    down: { options: Breakpoints },
    up: { options: Breakpoints },
  },
};

export default meta;
type Story = StoryObj<typeof Hidden>;

export const Basic: Story = {
  tags: ["visual-test"],
  args: {
    on: "xxs",
  },
  parameters: { docs: { source: { type: "code" }}},
  render: (args) => {
    const { breakpoint: BPS } = tokens.responsive;
    const nextBP = (bp: string) => {
      const names = Object.keys(BPS);
      const next = names[names.indexOf(bp) + 1];
      if (!next) return "more";
      return BPS[next as keyof typeof BPS];
    };
    const ResponsiveComponent = ({ children, hiddenOn, ...rest }: any) => (
      <div {...rest} style={{ padding: "8px", backgroundColor: "#f0f4f6" }}>
        <Inline spacing="1-x">
          <div>{children}</div>
          {hiddenOn.map((bp: string) => (
            <Chip
              key={bp}
              label={`${bp} (${BPS[bp as keyof typeof BPS]} - ${nextBP(bp)})`}
              style={{ backgroundColor: "#ddd" }}
            />
          ))}
        </Inline>
      </div>
    );

    return (
      <Stack spacing="1-x">
        <Hidden {...args}>
          <ResponsiveComponent hiddenOn={["xxs"]}>
            Hidden on="xxs"
          </ResponsiveComponent>
        </Hidden>
        <Hidden on={["xs", "sm", "md"]}>
          <ResponsiveComponent hiddenOn={["xs", "sm", "md"]}>
            Hidden on=["xs", "sm", "md"]
          </ResponsiveComponent>
        </Hidden>
        <Hidden on={["xl", "xxl"]}>
          <ResponsiveComponent hiddenOn={["xl", "xxl"]}>
            Hidden on=["xl", "xxl"]
          </ResponsiveComponent>
        </Hidden>
        <Hidden up="md">
          <ResponsiveComponent hiddenOn={["md", "lg", "xl", "xxl"]}>
            Hidden up="md"
          </ResponsiveComponent>
        </Hidden>
        <Hidden up="lg">
          <ResponsiveComponent hiddenOn={["lg", "xl", "xxl"]}>
            Hidden up="lg"
          </ResponsiveComponent>
        </Hidden>
        <Hidden down="md">
          <ResponsiveComponent hiddenOn={["xxs", "xs", "sm"]}>
            Hidden down="md"
          </ResponsiveComponent>
        </Hidden>
      </Stack>
    );
  },
};

export const Open: Story = {
  render: () => (
    <Button
      variant="primary"
      icon={<Launch />}
      onClick={() =>
        window.open("iframe.html?id=components-hidden--basic", "_blank")
      }
    >
      Open example
    </Button>
  ),
};
